function parseDateFromSheet(dateStr) {
  if (!dateStr) return null;
  const raw = String(dateStr).trim();
  if (!raw || raw.toLowerCase() === 'data' || raw.toLowerCase() === 'dados') return null;

  const parts = raw.split('/');
  if (parts.length !== 3) return null;

  const day = Number(parts[0]);
  const month = Number(parts[1]);
  const year = Number(parts[2]);
  if (!Number.isInteger(day) || !Number.isInteger(month) || !Number.isInteger(year)) return null;
  if (day < 1 || day > 31 || month < 1 || month > 12 || year < 2000) return null;

  const date = new Date(year, month - 1, day);
  date.setHours(0, 0, 0, 0);
  return Number.isNaN(date.getTime()) ? null : date;
}

function formatDateToSQL(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

const parsedDates = [];
for (const item of items) {
  if (item.json.values && Array.isArray(item.json.values)) {
    for (const row of item.json.values) {
      const date = parseDateFromSheet(Array.isArray(row) ? row[0] : row);
      if (date) parsedDates.push(date);
    }
  }

  const directValue = item.json.dados ?? item.json.data ?? item.json.A;
  const directDate = parseDateFromSheet(directValue);
  if (directDate) parsedDates.push(directDate);
}

const today = new Date();
today.setHours(0, 0, 0, 0);

if (parsedDates.length === 0) {
  return [{ json: { target_date: formatDateToSQL(today) } }];
}

const lastDate = parsedDates.reduce((maxDate, currentDate) => {
  return currentDate > maxDate ? currentDate : maxDate;
});

if (lastDate >= today) {
  return [];
}

const missingDates = [];
let currentDate = new Date(lastDate);
currentDate.setDate(currentDate.getDate() + 1);

while (currentDate <= today) {
  missingDates.push({
    json: {
      target_date: formatDateToSQL(currentDate)
    }
  });
  currentDate.setDate(currentDate.getDate() + 1);
}

return missingDates;

const out = [];
const fmtPct = (value) => {
  if (value === null || value === undefined || value === '') return '';
  return Number(value).toFixed(2).replace('.', ',') + '%';
};
for (const item of items) {
  const row = item.json;

  // Evita append de dias sem qualquer registro no banco
  if (Number(row.total_registros ?? 0) === 0) {
    continue;
  }

  out.push({
    json: {
      'data': row.data ?? '',
      'ocupado': row.ocupado ?? '',
      'livre': row.livre ?? '',
      'cedido': row.cedido ?? '',
      'impedido': row.impedido ?? '',
      'reservado': row.reservado ?? '',
      'taxa de ocupaçao geral': fmtPct(row.taxa_ocupacao_pct),
      'percentual de leitos impedidos': fmtPct(row.percentual_impedidos_pct),
      'pacientes 60+': row.pacientes_60mais ?? '',
      'pacientes <= 17': row.pacientes_menor17 ?? '',
      'pacientes mulher': row.pacientes_mulher ?? '',
      'pacientes homem': row.pacientes_homem ?? '',
      'total de pacientes longa permanência > 15dias': row.longa_permanencia_gt15 ?? '',
      'total de pacientes de longa permanência com mais de 60 anos': row.longa_permanencia_60mais ?? ''
    }
  });
}
return out;
